package com.iipxp.beemacro;

import java.util.ArrayList;
import java.util.List;

/**
 * Reads the stack text on a buff icon ("x31", "x1.18", "11%"): white glyphs with a black outline in the lower part
 * of the slot. Glyphs are split by column gaps in the white mask, normalised to GW×GH and matched to templates that
 * were cut from real screenshots by {@code test/OcrTrain.java} (see GLYPHS). Returns null when nothing readable.
 */
public final class StackOcr {
    public static final int GW = 7, GH = 10;
    /** char -> GW*GH mask ('#' on). Generated by test/OcrTrain.java from labelled screenshots; regenerate, don't edit. */
    static String[][] GLYPHS = {
        {"0", "...#....#..##........#.....##.....##.....##.....#.#......#####....#..."},   // 1 samples
        {"1", "...###################################################################"},   // 12 samples
        {"2", "...##..##...#.......#.....#.....##...###...##.....#.....#.#....#######"},   // 10 samples
        {"3", ".#####......#......#.....##....###......##.....####...##.#####...##..."},   // 8 samples
        {"4", "....##....###...##.#...#..#..##..#.##..#####.####.....#......#......#."},   // 2 samples
        {"5", "######.##.....##.##..#####..##...##.....##.....##.....#.#####...##...."},   // 4 samples
        {"6", "...##....##....##....##.....####...##....###....###...####...##..###.."},   // 1 samples
        {"7", ".#####......#......#.#...#..###.#.#.#.##..##.##.....#......#.........."},   // 1 samples
        {"8", "..###...#...#.##...####...#..#####.##...####...####....###...##..###.."},   // 7 samples
        {"9", "..###..#....####...###....####...##..####......#......#.....#....##..."},   // 8 samples
        {"x", "##...#..##.##..##.##...###.....#.....###...##.##..##.##.##..##.#.....#"},   // 23 samples
    };

    static boolean white(int p) { return ((p >> 16) & 255) > 205 && ((p >> 8) & 255) > 205 && (p & 255) > 205; }
    static boolean dark(int p) { return Math.max((p >> 16) & 255, Math.max((p >> 8) & 255, p & 255)) < 70; }
    /** Stack text = white with the black outline close by (icon art can be white too, but is not outlined in black). */
    static boolean text(int[] px, int w, int x, int y) {
        if (!white(px[y * w + x])) return false;
        int R = 8, hits = 0;
        for (int d = 1; d <= R; d++) { if (x - d >= 0 && dark(px[y * w + x - d])) { hits++; break; } }
        for (int d = 1; d <= R; d++) { if (x + d < w && dark(px[y * w + x + d])) { hits++; break; } }
        for (int d = 1; d <= R; d++) { int yy = y - d; if (yy >= 0 && dark(px[yy * w + x])) { hits++; break; } }
        for (int d = 1; d <= R; d++) { int yy = y + d; if (yy * w + x < px.length && dark(px[yy * w + x])) { hits++; break; } }
        return hits >= 2;
    }

    /** Glyph masks (left to right) inside the slot's text band. */
    public static List<boolean[]> glyphs(int[] px, int w, int h, double x0, double y0, double size) {
        int X0 = (int) Math.round(x0), X1 = (int) Math.round(x0 + size), Y0 = (int) Math.round(y0 + size * 0.55), Y1 = Math.min(h - 1, (int) Math.round(y0 + size * 1.04));
        // column runs of white = glyph candidates, with their vertical extent
        List<int[]> runs = new ArrayList<>();
        int x = X0, maxH = 0;
        while (x < X1) {
            while (x < X1 && !colHas(px, w, x, Y0, Y1)) x++;
            int a = x;
            while (x < X1 && colHas(px, w, x, Y0, Y1)) x++;
            int b = x;
            if (b - a < 2) continue;
            int t = Y1, u = Y0;
            for (int yy = Y0; yy <= Y1; yy++) for (int xx = a; xx < b; xx++) if (text(px, w, xx, yy)) { t = Math.min(t, yy); u = Math.max(u, yy); }
            if (u - t < 2) continue;
            runs.add(new int[]{a, b, t, u}); maxH = Math.max(maxH, u - t + 1);
        }
        List<boolean[]> out = new ArrayList<>();
        for (int[] r : runs) {
            int a = r[0], b = r[1], t = r[2], u = r[3], hh = u - t + 1;
            if (hh < 0.45 * maxH) { if (b - a <= 0.5 * maxH && u > Y0 + (Y1 - Y0) / 2) out.add(DOT); continue; }   // decimal point
            int k = SPLIT ? Math.max(1, (int) Math.round((b - a) / (0.62 * maxH))) : 1;    // touching glyphs: split evenly
            for (int q = 0; q < k; q++) out.add(cell(px, w, a + (b - a) * q / k, a + (b - a) * (q + 1) / k, t, u));
        }
        return out;
    }
    static final boolean[] DOT = new boolean[0];
    public static boolean SPLIT = false;
    private static boolean[] cell(int[] px, int w, int a, int b, int t, int u) {
        boolean[] g = new boolean[GW * GH];
        for (int j = 0; j < GH; j++) for (int i = 0; i < GW; i++) {
            int sx = a + (int) ((i + 0.5) * (b - a) / GW), sy = t + (int) ((j + 0.5) * (u - t + 1) / GH);
            g[j * GW + i] = text(px, w, sx, sy);
        }
        return g;
    }
    private static boolean colHas(int[] px, int w, int x, int y0, int y1) { int n = 0; for (int y = y0; y <= y1; y++) if (text(px, w, x, y) && ++n >= 2) return true; return false; }

    /** Tablet Haste count: no "xN" text = 1; otherwise the digits after the x, or -1 if they cannot be read. */
    public static int hasteCount(int[] px, int w, int h, double x0, double y0, double size) {
        List<boolean[]> gs = glyphs(px, w, h, x0, y0, size);
        if (gs.size() < 2) return 1;
        int n = 0;
        for (boolean[] g : gs.subList(1, gs.size())) {
            if (g == DOT) return -1;
            char best = (char) 0; double bs = 0;
            for (String[] t : GLYPHS) {
                if (!Character.isDigit(t[0].charAt(0))) continue;
                int same = 0; for (int i = 0; i < GW * GH; i++) if (g[i] == (t[1].charAt(i) == (char) 35)) same++;
                double sc = same / (double) (GW * GH);
                if (sc > bs) { bs = sc; best = t[0].charAt(0); }
            }
            if (bs < 0.72) return -1;   // the runner icon often overlaps the digits: better unknown than wrong
            n = n * 10 + (best - (char) 48);
        }
        return n >= 1 && n <= 10 ? n : -1;
    }

    /** Text read from the slot, or null if a glyph doesn't match any template well enough. */
    public static String read(int[] px, int w, int h, double x0, double y0, double size) { return read(px, w, h, x0, y0, size, 0.80); }

    /** minScore: how closely each glyph must match; rescaled tablet icons need a lower bar. */
    public static String read(int[] px, int w, int h, double x0, double y0, double size, double minScore) {
        List<boolean[]> gs = glyphs(px, w, h, x0, y0, size);
        if (gs.isEmpty() || GLYPHS.length == 0) return null;
        StringBuilder s = new StringBuilder();
        for (boolean[] g : gs) {
            if (g == DOT) { s.append('.'); continue; }
            char best = '?'; double bs = 0;
            for (String[] t : GLYPHS) {
                int same = 0; for (int i = 0; i < GW * GH; i++) if (g[i] == (t[1].charAt(i) == '#')) same++;
                double sc = same / (double) (GW * GH);
                if (sc > bs) { bs = sc; best = t[0].charAt(0); }
            }
            if (bs < minScore) return null;
            s.append(best);
        }
        String r = s.toString();
        return r.matches("x[0-9]+(\\.[0-9]+)?|[0-9]+%") ? r : null;   // only well-formed stack/percent text
    }
}
